Iap_Dev_ID iap_rd_device_id (void)
{
  UInt32 arg_i [5] , arg_o [5] ;

  arg_i [0] = CMD_RD_DEVICE_ID ;

  iap_execute (arg_i , arg_o)  ;

  return (Iap_Dev_ID)  arg_o [1] ;
}

